using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Text.Json;using GameTranslator.Translation;
namespace GameTranslator.App.Views;
public sealed class TranslationHistoryWindow:Window {
 private sealed record Row(string Game,string Engine,string English,string Arabic);
 public TranslationHistoryWindow(string path){Title="سجل الترجمة وتصحيح الأخطاء";Width=760;Height=720;MinWidth=500;MinHeight=500;FlowDirection=FlowDirection.RightToLeft;Background=new SolidColorBrush(Color.FromRgb(18,24,35));Foreground=Brushes.White;
  Resources.MergedDictionaries.Add(new ResourceDictionary{Source=new Uri("/GameTranslator;component/Theme/ArabicTestStyles.xaml",UriKind.Relative)});var root=new StackPanel{Margin=new Thickness(18)};Content=new ScrollViewer{Content=root,PanningMode=PanningMode.VerticalOnly,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
  TextBlock Text(string text,int size=16)=>new(){Text=text,FontSize=size,Foreground=Brushes.White,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(5)};
  root.Children.Add(Text("الأخطاء والتصحيحات",25));root.Children.Add(Text("اعتمادك يصحح الجملة نفسها في اللعبة نفسها على جهازك. إرسال البلاغ يفتح GitHub لتراجعه وترسله من حسابك؛ لا نرفع السجل كاملًا. التصحيح العام لا يُوزع قبل المراجعة."));
  var auto=new CheckBox{Content="تنزيل التصحيحات العامة المراجعة تلقائيًا",IsChecked=CommunityCorrections.Automatic,Foreground=Brushes.White,MinHeight=44};auto.Checked+=(_,_)=>{CommunityCorrections.Automatic=true;_=CommunityCorrections.RefreshAsync();};auto.Unchecked+=(_,_)=>CommunityCorrections.Automatic=false;root.Children.Add(auto);
  var records=new List<Row>();try{if(System.IO.File.Exists(path)&&new System.IO.FileInfo(path).Length<=11_000_000){var queue=new Queue<Row>();foreach(var line in System.IO.File.ReadLines(path)){try{using var doc=JsonDocument.Parse(line);var e=doc.RootElement;queue.Enqueue(new Row(e.GetProperty("Game").GetString()??"",e.GetProperty("Engine").GetString()??"",e.GetProperty("English").GetString()??"",e.GetProperty("Arabic").GetString()??""));while(queue.Count>200)queue.Dequeue();}catch(JsonException){}}records=queue.Reverse().ToList();}}catch{}
  var choice=new ComboBox{MinHeight=48,Margin=new Thickness(5)};foreach(var row in records)choice.Items.Add(new ComboBoxItem{Content=row.Game+" · "+row.English[..Math.Min(100,row.English.Length)],Tag=row});root.Children.Add(choice);var english=Text("");english.FlowDirection=FlowDirection.LeftToRight;root.Children.Add(english);var original=Text("");root.Children.Add(original);var corrected=new TextBox{AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=90,MaxLength=3000,Margin=new Thickness(5)};root.Children.Add(Text("التصحيح العربي المقترح"));root.Children.Add(corrected);var state=Text("");
  Row? selected=null;choice.SelectionChanged+=(_,_)=>{selected=(choice.SelectedItem as ComboBoxItem)?.Tag as Row;english.Text=selected?.English??"";original.Text=selected?.Arabic??"";corrected.Text=selected?.Arabic??"";};
  void Button(string title,Action task){var button=new Button{Content=title,MinHeight=48,Margin=new Thickness(5)};button.Click+=(_,_)=>task();root.Children.Add(button);}
  Button("اعتماد التصحيح على جهازي",()=>{if(selected==null)return;try{CommunityCorrections.SavePersonal(selected.Game,selected.English,corrected.Text);state.Text="حُفظ التصحيح محليًا؛ سيُستخدم للجملة نفسها قبل طلب المحرك.";}catch{state.Text="تعذر حفظ التصحيح؛ تحقق أن النص غير فارغ.";}});
  Button("الإبلاغ عن خطأ لغوي للمراجعة",()=>{if(selected==null)return;var body=JsonSerializer.Serialize(new{game=selected.Game,engine=selected.Engine,source=selected.English,arabic=selected.Arabic,proposed=corrected.Text},new JsonSerializerOptions{WriteIndented=true,Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping});
   if(MessageBox.Show(this,body+"\n\nسيُنسخ هذا السطر فقط وتُفتح صفحة GitHub. الصقه وراجعه ثم أرسله من حسابك. لا توجد بيانات مفاتيح أو ربط.","مراجعة البلاغ",MessageBoxButton.OKCancel)!=MessageBoxResult.OK)return;
   try{var folder=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ArabicGames","Quality","reports");System.IO.Directory.CreateDirectory(folder);System.IO.File.WriteAllText(System.IO.Path.Combine(folder,Guid.NewGuid().ToString("N")+".json"),body);Clipboard.SetText(body);System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("https://github.com/Tariq-220/ArabicGamesTranslator/issues/new?template=translation-error.yml"){UseShellExecute=true});state.Text="حُفظ البلاغ ونُسخ. الصقه في GitHub وأرسله؛ لم يُنشر تلقائيًا.";}catch{state.Text="تعذر فتح صفحة البلاغ؛ المحفوظ محليًا لا يُرفع تلقائيًا.";}});
  root.Children.Add(state);Button("إغلاق",Close);if(choice.Items.Count>0)choice.SelectedIndex=0;else state.Text="لا توجد سطور محفوظة بعد. فعّل السجل وشغّل الترجمة أولًا.";
 }
}
